const FEEDS = [
  {
    publisher: 'Golem',
    topic: 'Internet',
    feedUrl: 'https://rss.golem.de/rss.php?ms=internet&feed=RSS2.0',
  },
  {
    publisher: 'Golem',
    topic: 'Open-Source',
    feedUrl: 'https://rss.golem.de/rss.php?ms=open-source&feed=RSS2.0',
  },
  {
    publisher: 'Golem',
    topic: 'Security',
    feedUrl: 'https://rss.golem.de/rss.php?ms=security&feed=RSS2.0',
  },
  {
    publisher: 'Golem',
    topic: 'Softwareentwicklung',
    feedUrl: 'https://rss.golem.de/rss.php?ms=softwareentwicklung&feed=RSS2.0',
  },
];

const SEG = /^[A-Za-z0-9._-]+$/;

function berlinDateString(date) {
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/Berlin',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(date);
}

function addCivilDays(ymd, delta) {
  const [y, m, d] = ymd.split('-').map(Number);
  const t = Date.UTC(y, m - 1, d) + delta * 86400000;
  return new Date(t).toISOString().slice(0, 10);
}

const targetDay = addCivilDays(berlinDateString(new Date()), -1);

return FEEDS.map((feed) => {
  const publisher = String(feed.publisher || '').trim();
  const topic = String(feed.topic || '').trim();
  if (!SEG.test(publisher) || !SEG.test(topic)) {
    throw new Error(`Invalid publisher/topic "${publisher}"/"${topic}"`);
  }
  const feedName = `${publisher}-${topic}`;
  return {
    json: {
      publisher,
      topic,
      feedName,
      feedUrl: String(feed.feedUrl || '').trim(),
      targetDay,
      folder: `/News/${targetDay}`,
      filename: `${feedName}.pdf`,
    },
  };
});

const EXTRACTOR = 'http://article-extractor:8080';

const feed = $input.first().json;
const { feedName, feedUrl, targetDay, folder, filename } = feed;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: `${EXTRACTOR}/v1/feed-day-pdf`,
  headers: { 'Content-Type': 'application/json' },
  body: {
    feed_url: feedUrl,
    day: targetDay,
    feed_title: feedName,
    max_articles: 25,
  },
  encoding: 'arraybuffer',
  returnFullResponse: true,
  timeout: 300000,
});

const status = response.statusCode || response.status || 0;
if (status === 204) {
  return [
    {
      json: {
        feedName,
        feedUrl,
        targetDay,
        folder,
        filename,
        skipped: true,
        articleCount: 0,
        reason: 'no articles for target day',
      },
    },
  ];
}

if (status < 200 || status >= 300) {
  const body = response.body;
  const detail = Buffer.isBuffer(body)
    ? body.toString('utf8')
    : typeof body === 'string'
      ? body
      : JSON.stringify(body ?? '');
  throw new Error(`article-extractor failed for ${feedName} (status=${status}): ${String(detail).slice(0, 500)}`);
}

function asBuffer(payload) {
  if (Buffer.isBuffer(payload)) return payload;
  if (payload?.type === 'Buffer' && Array.isArray(payload.data)) {
    return Buffer.from(payload.data);
  }
  if (payload instanceof ArrayBuffer) return Buffer.from(payload);
  if (ArrayBuffer.isView(payload)) {
    return Buffer.from(payload.buffer, payload.byteOffset, payload.byteLength);
  }
  if (typeof payload === 'string') return Buffer.from(payload, 'binary');
  throw new Error(`Unexpected PDF payload type: ${typeof payload}`);
}

const pdf = asBuffer(response.body);
if (pdf.length < 100 || pdf.slice(0, 4).toString() !== '%PDF') {
  throw new Error(`article-extractor returned non-PDF (${pdf.length} bytes)`);
}

const headers = response.headers || {};
const articleCount = Number(headers['x-article-count'] || headers['X-Article-Count'] || 0);
const failedCount = Number(headers['x-failed-count'] || headers['X-Failed-Count'] || 0);
const binary = await this.helpers.prepareBinaryData(pdf, filename, 'application/pdf');

return [
  {
    json: {
      feedName,
      feedUrl,
      targetDay,
      folder,
      filename,
      skipped: false,
      articleCount,
      failedCount,
    },
    binary: { data: binary },
  },
];
